WITH item_returns AS (SELECT d.d_year, d.d_quarter_seq, cr.cr_item_sk, SUM(cr.cr_return_quantity) AS total_qty, SUM(cr.cr_return_amount) AS total_amount, COUNT(*) AS return_events FROM catalog_returns cr JOIN date_dim d ON cr.cr_returned_date_sk = d.d_date_sk GROUP BY d.d_year, d.d_quarter_seq, cr.cr_item_sk), ranked_items AS (SELECT *, ROW_NUMBER() OVER (PARTITION BY d_year, d_quarter_seq ORDER BY total_qty DESC) AS qty_row FROM item_returns) SELECT r.d_year, r.d_quarter_seq, r.cr_item_sk, r.total_qty, r.total_amount, r.return_events FROM ranked_items r WHERE r.qty_row <= 5 AND r.total_amount > 1000 ORDER BY r.d_year, r.d_quarter_seq, r.qty_row
